export const MESSAGE_LABEL = 'Built-in (rule-based)'
export const POOLS = P
const hash = (s: string) => { let h = 2166136261; for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619); return h >>> 0 }
/** Deterministic: the same seed always gives the same line, so the bubble never flickers between renders. */
export const pickMessage = (state: BuddyState, style: BuddyStyle, seed: string) => { const pool = P[state][style]; return pool[hash(`${state}|${style}|${seed}`) % pool.length] }
